-- parameters: ["-","EA","","1","2","3"]
SELECT UPPER(LIPS.MATNR) AS "upper", LOWER(LIPS.VRKME) AS "lower", TRIM(LIPS.VBELN) AS "trimmed", (LIPS.MATNR || ? || LIPS.VRKME) AS "joined", COALESCE(LIPS.VRKME, ?) AS "fallback", NULLIF(LIPS.VRKME, ?) AS "emptyUnit", (LIPS.LFIMG + LIPS.LFIMG) AS "total", (LIPS.LFIMG - ?) AS "difference", (LIPS.LFIMG * ?) AS "product", (LIPS.LFIMG / ?) AS "ratio", ABS(LIPS.LFIMG) AS "magnitude", ROUND(LIPS.LFIMG, 1) AS "rounded", CAST(LIPS.LFIMG AS NVARCHAR(20)) AS "asText", CAST(LIPS.MATNR AS DECIMAL(15,3)) AS "asDecimal", CAST(LIPS.LFIMG AS INTEGER) AS "asInteger", CAST(LIPS.LFIMG AS DOUBLE) AS "asDouble", CAST(LIPS.VGBEL AS DATE) AS "asDate", CAST(LIPS.VGBEL AS TIMESTAMP) AS "asTimestamp"
FROM QUERY_IT.LIPS LIPS
